colorData = crossfilter(jsonColorData);
dimensionColorData = colorData.dimension(function (d) { return [+d.colData, +d.rowData]; });
groupColorData = dimensionColorData.group().reduceSum(function(d) { return +d.colorData; });

var dataCleaner = function(e) {
    e.dd = d3.time.format.iso.parse(e.date);
};

json.forEach(dataCleaner);
json2.forEach(dataCleaner);

data = crossfilter(json);

groupAll = data.groupAll();
groupAll2 = data.groupAll();

dateFormat = d3.time.format("%Y-%m-%d");

valueDimension = data.dimension(function(d) {
    return d.value;
});
valueGroup = valueDimension.group();

valueNegValSumGroup = valueDimension.group().reduceSum(function(d){return -Math.abs(+d.nvalue);});
valuePosValSumGroup = valueDimension.group().reduceSum(function(d){return Math.abs(+d.nvalue);});
valueMixValSumGroup = valueDimension.group().reduceSum(function(d){return +d.nvalue;});

countryDimension = data.dimension(function(d) {
    return d.countrycode;
});
countryGroup = countryDimension.group();

statusDimension = data.dimension(function(d) {
    return d.status;
});
statusGroup = statusDimension.group();
statusMultiGroup = statusGroup.reduce(
    //add
    function(p, v) {
        ++p.count;
        p.value += +v.value;
        return p;
    },
    //remove
    function(p, v) {
        --p.count;
        p.value -= +v.value;
        return p;
    },
    //init
    function() {
        return {count:0, value:0};
    }
);

regionDimension = data.dimension(function(d) {
    return d.region;
});
regionGroup = regionDimension.group();

dateDimension = data.dimension(function(d) {
    return d3.time.day(d.dd);
});
dateGroup = dateDimension.group();
dateValueSumGroup = dateDimension.group().reduceSum(function(d){return d.value;});
dateIdSumGroup = dateDimension.group().reduceSum(function(d){return d.id;});
dateFixedSumGroup = dateDimension.group().reduceSum(function(d){return 5;});
dateNegativeValueSumGroup = dateDimension.group().reduceSum(function(d){return d.nvalue;});

stateDimension = data.dimension(function(d){return d.state;});
stateGroup = stateDimension.group();
stateValueSumGroup = stateDimension.group().reduceSum(function(d){return d.value;});

// TODO
districtDimension = data.dimension(function(d){return d.district;});
districtValueEnrollGroup = districtDimension.group().reduceSum(function(d){return d.value;});

resetAllFilters = function() {
    valueDimension.filterAll();
    countryDimension.filterAll();
    statusDimension.filterAll();
    regionDimension.filterAll();
    dateDimension.filterAll();
    stateDimension.filterAll();
};

resetBody = function(){
    document.body.innerHTML = '';
};
